-- Volcando datos para la tabla restaurant_rico.productos: ~7 rows (aproximadamente)
INSERT INTO `productos` (`id_producto`, `id_categoria`, `nombre`, `descripcion`, `precio`, `imagen`, `estado`) VALUES
	(2, 1, 'Pescado Entero', 'Deliciosa receta cubana de Pescado frito entero, muy crujiente y fácil de hacer para que deleites a tus invitados en casa.', 13.59, _binary , 1),
	(3, 1, 'Filete de Pescado Frito', 'Una forma sencilla y rápida de preparar el pescado es freírlo bañado previamente en harina, así tenemos una pieza crujiente y suave. Si miras la receta verás que es parecida al chicharrón de pescado, pero en esta ocasión uso filetes de pescado y un aderezo diferente.', 7.50, _binary , 1),
	(4, 2, 'Arroz con Camarón', 'Disfruta de un festín marino en casa con nuestra deliciosa receta de camarones. Con solo hervirlos y combinarlos con un colorido refrito de verduras y arroz al gusto, podrás sorprender a tu familia con un platillo lleno de sabor y frescura.', 8.00, _binary , 1),
	(5, 2, 'Arroz con calamar', 'Este arroz con calamares es una de las recetas clásicas de arroz, al igual que estas otras recetas de arroz con bogavante, este arroz con conejo o el tradicional arroz con bacalao.', 8.00, _binary , 1);
INSERT INTO `productos` (`id_producto`, `id_categoria`, `nombre`, `descripcion`, `precio`, `imagen`, `estado`) VALUES
	(6, 4, 'Encebollado Sencillo', 'El encebollado manaba es un plato tradicional de Ecuador, donde se destaca la combinación de pescado, cebolla, yuca y especias como el comino y el ají en un caldo sabroso y reconfortante. Ideal para disfrutar en cualquier época del año. Una verdadera delicia llena de sabor y tradición.', 3.00, _binary , 1);
INSERT INTO `productos` (`id_producto`, `id_categoria`, `nombre`, `descripcion`, `precio`, `imagen`, `estado`) VALUES
	(7, 4, 'Encebollado Mixto', 'Esto más que una sopa es un potaje, una suerte de brebaje vigorizante. El encebollado es un concentrado tanto de pescado fresco (albacora de preferencia), como de hierbas aromáticas, pero también de yuca y vegetales cocidos.', 6.00, _binary , 1),
	(8, 3, 'Encocado de Camarón', 'Plato típico de la provincia de Esmeraldas, ideal para cualquier ocasión. Los camarones pueden ser reemplazados por pescado o calamares.', 8.00, _binary , 1),
	(9, 3, 'Encocado de Concha', 'Deli concha', 9.00, _binary , 1),
	(10, 3, 'aadsad', 'adadsasdd', 2.00, _binary , 1);

